sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.name = c.data.templateData.name || "";
    c.description = c.data.templateData.description || "";
    c.category = c.data.templateData.category || "";
    c.save = function() {
        c.server.get({
            action: "save",
            name: c.name,
            description: c.description,
            category: c.category
        }).then(function(r) {
            c.data.saved = r.data.saved;
            c.data.templateId = r.data.templateId;
        });
    };
};

sp_widget.script:
(function() {
    data.templateId = $sp.getParameter("template_id") || "";
    data.templateData = {};
    data.sections = [];
    data.saved = false;
    try {
        if (data.templateId) {
            var gr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
            if (gr.get(data.templateId)) {
                data.templateData = {
                    name: gr.getValue("name"),
                    template_key: gr.getValue("template_key"),
                    description: gr.getValue("description"),
                    application_type: gr.getDisplayValue("application_type"),
                    status: gr.getDisplayValue("status"),
                    version: gr.getValue("version"),
                    is_default: gr.getValue("is_default") === "1",
                    active: gr.getValue("active") === "1"
                };
            }
            // Load sections via junction table
            var tsGr = new GlideRecord("x_1433041_identi_0_template_section");
            tsGr.addQuery("template", data.templateId);
            tsGr.addQuery("active", true);
            tsGr.orderBy("order");
            tsGr.setLimit(50);
            tsGr.query();
            while (tsGr.next()) {
                var secGr = new GlideRecord("x_1433041_identi_0_section");
                if (secGr.get(tsGr.getValue("section"))) {
                    data.sections.push({
                        sys_id: secGr.getValue("sys_id"),
                        ts_sys_id: tsGr.getValue("sys_id"),
                        name: secGr.getValue("name"),
                        section_key: secGr.getValue("section_key"),
                        order: tsGr.getValue("order")
                    });
                }
            }
        }
        if (input && input.action === "save") {
            var tGr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
            if (data.templateId && tGr.get(data.templateId)) {
                tGr.setValue("name", input.name);
                tGr.setValue("description", input.description || "");
                if (input.application_type) tGr.setValue("application_type", input.application_type);
                if (input.version) tGr.setValue("version", input.version);
                tGr.update();
                data.saved = true;
            } else {
                var nGr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
                nGr.initialize();
                nGr.setValue("name", input.name);
                nGr.setValue("template_key", input.name.toLowerCase().replace(/[^a-z0-9]+/g, "_"));
                nGr.setValue("description", input.description || "");
                nGr.setValue("status", "draft");
                nGr.setValue("version", "1.0");
                nGr.setValue("active", true);
                data.templateId = nGr.insert();
                data.saved = true;
            }
            return;
        }
        if (input && input.action === "activate") {
            var aGr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
            if (data.templateId && aGr.get(data.templateId)) {
                aGr.setValue("status", "published");
                aGr.setValue("published_at", new GlideDateTime().getValue());
                aGr.setValue("published_by", gs.getUserID());
                aGr.update();
                data.templateData.status = "Published";
            }
            return;
        }
        if (input && input.action === "deactivate") {
            var dGr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
            if (data.templateId && dGr.get(data.templateId)) {
                dGr.setValue("status", "draft");
                dGr.setValue("active", false);
                dGr.update();
                data.templateData.status = "Draft";
                data.templateData.active = false;
            }
            return;
        }
    } catch (e) {
        gs.error("IBAR Template Form widget error: " + e.message);
    }
})();
